import java.util.*;

class Solution {
  public boolean[] friendRequests(int n, int[][] restrictions, int[][] requests) {
    int[] p = new int[n];
    for (int i = 0; i < n; i++) p[i] = i;
    boolean[] ans = new boolean[requests.length];
    for (int q = 0; q < requests.length; q++) {
      int a = find(p, requests[q][0]), b = find(p, requests[q][1]);
      if (a == b) {
        ans[q] = true;
        continue;
      }
      boolean ok = true;
      for (int[] r : restrictions) {
        int x = find(p, r[0]), y = find(p, r[1]);
        if ((x == a && y == b) || (x == b && y == a)) {
          ok = false;
          break;
        }
      }
      if (ok) {
        p[a] = b;
        ans[q] = true;
      }
    }
    return ans;
  }

  private int find(int[] p, int x) {
    while (p[x] != x) {
      p[x] = p[p[x]];
      x = p[x];
    }
    return x;
  }
}
